<?php namespace App\Http\Controllers; use App\Models\FollowUp;use App\Models\Lead;use App\Models\User;use Illuminate\Http\Request;class FollowUpController extends Controller {public function index(){$followUps=FollowUp::with(['lead','assignee'])->orderByRaw("CASE WHEN status='pending' THEN 0 ELSE 1 END")->orderBy('due_at')->paginate(15);$leads=Lead::orderBy('first_name')->get();$users=User::orderBy('name')->get();return view('followups.index',compact('followUps','leads','users'));}public function store(Request $r){$d=$r->validate(['lead_id'=>'required|exists:leads,id','assigned_to'=>'required|exists:users,id','due_at'=>'required|date','type'=>'required|in:Call,Email,LinkedIn Message,Meeting,Other','notes'=>'required|string|max:3000']);$d['status']='pending';FollowUp::create($d);return back()->with('success','Reminder scheduled.');}public function complete(FollowUp $followUp){$followUp->update(['status'=>'completed','completed_at'=>now()]);$followUp->lead()->update(['last_contacted_at'=>now()]);return back()->with('success','Follow-up completed.');}}